// PG Diploma in Early Intervention, Paper II Child Development. Written in Learn Anywhere's own words.
window.LIB_EXTRA = (window.LIB_EXTRA || []).concat([
{
  id:"growth-development-principles", title:"Growth and development: concepts, principles, stages, tasks and hazards", subject:"Early Intervention: Child development", region:"Paper II Child Development", stages:"steps",
  aliases:["principles of development","laws of development","cephalocaudal proximodistal","developmental tasks Havighurst","nature and nurture","factors affecting development","developmental hazards"],
  simple:"Growth is the increase in body size that we can measure, such as weight and height. Development is the gain in skills and abilities, such as walking, talking and making friends. Development follows predictable rules and is shaped by both the genes a child is born with and the care and surroundings the child grows up in.",
  flow:["Growth: measurable increase in size (quantitative)","Development: progressive gain in function and skill (qualitative)","Follows laws: cephalocaudal, proximodistal, general to specific","Unfolds in stages, each with expected developmental tasks","Shaped by heredity and environment acting together","Hazards spotted early allow timely early intervention"],
  exam:[
    {h:"Definitions", p:["Growth: increase in the size of the body or its parts, measured by weight, length or height and head circumference; it is quantitative and largely stops after adolescence.","Development: orderly, progressive change leading to new abilities and maturity in function; it is qualitative and continues through life (Hurlock describes it as a series of orderly changes resulting from maturation and experience).","Maturation is change driven by genetic timing; learning is change driven by practice and experience; development needs both."]},
    {h:"Principles and laws of development", p:["Development is continuous, orderly and follows a predictable sequence, but the rate differs between children (individual differences).","Cephalocaudal: control spreads from head to feet (head control before sitting before walking). Proximodistal: from the trunk outward to shoulder, then hand, then fingers.","General to specific (mass to specific): whole-body startle movements come before precise reaching; gross before fine.","Development is interrelated across domains, depends on maturation and learning, can be predicted, and early foundations are critical.","Each phase has characteristic behaviour; some stages carry social expectations and hazards."]},
    {h:"Stages and developmental tasks", p:["Hurlock's life stages: prenatal, infancy (birth-2 weeks), babyhood (to 2 years), early childhood (2-6 years), late childhood (6 years to puberty), puberty, adolescence and adulthood.","Developmental task (Havighurst): a task arising at a certain period whose successful achievement leads to happiness and success with later tasks, while failure leads to unhappiness, social disapproval and difficulty later.","Tasks of infancy and early childhood: learning to walk, take solid food, talk, control elimination, learn sex differences, form simple concepts, relate emotionally to parents and siblings, and distinguish right from wrong.","Domains: motor (gross and fine), cognitive, language and communication, social, emotional, and adaptive or self-help."]},
    {h:"Nature, nurture and factors affecting development", p:["Nature: heredity, genetic and chromosomal makeup, sex, temperament and maturational timetable. Nurture: nutrition, stimulation, parenting, family, culture and socio-economic status.","Current view: they interact; genes set a range and the environment decides where in that range the child develops.","Prenatal factors: maternal nutrition, infections (TORCH), drugs, alcohol, radiation, maternal illness, Rh incompatibility.","Perinatal and postnatal: prematurity, low birth weight, birth asphyxia, neonatal jaundice, malnutrition, infections, poverty, lack of stimulation, family discord, abuse and neglect."]},
    {h:"Developmental hazards and early intervention", p:["Physical hazards: illness, malnutrition, accidents, sensory loss, obesity. Psychological hazards: delayed speech, emotional deprivation, poor family relationships, unrealistic parental expectations.","Identification: growth monitoring on WHO charts, developmental surveillance at each health or Anganwadi contact, and screening with tools such as TDSC; under RBSK children 0-6 years are screened for the 4 Ds (defects at birth, diseases, deficiencies, developmental delays) and referred to the DEIC.","Interventionist role: explain to parents that development is sequential, plan activities at the next step of the sequence, use daily routines (feeding, bathing, play) as learning times, and correct hazards such as poor nutrition or lack of play."]},
    {h:"Conclusion", p:["Knowing the laws and stages lets the early interventionist judge whether a child is on track, set goals in the right order, and involve the family before delays become fixed."]}
  ],
  tip:"Draw a baby outline with one arrow from head to feet (cephalocaudal) and one from trunk to fingertips (proximodistal); add a two-column box labelled Nature and Nurture with examples.",
  evidence:[["Responsive caregiving and early learning (nurturing care) programmes","Improve early child development outcomes","Strong"],["Early developmental surveillance and screening","Earlier detection and referral of delay","Moderate"],["Nutrition supplementation alone","Improves growth; effects on development are smaller and less consistent","Moderate"]],
  evidenceSource:"Lancet Early Childhood Development Series 2016 and WHO Nurturing Care Framework 2018",
  outcomes:[["WHO growth charts","Weight, length and head circumference against age"],["TDSC","Quick developmental screen 0-2 years"],["DASII","Motor and mental developmental quotient 0-30 months"]],
  recent:["WHO, UNICEF and World Bank launched the Nurturing Care Framework (2018): health, nutrition, responsive caregiving, safety and early learning."],
  mnemonic:{word:"CPGIP", items:[["C","Cephalocaudal"],["P","Proximodistal"],["G","General to specific"],["I","Individual differences"],["P","Predictable sequence"]], extra:"Growth is size you can measure; development is skill you can observe."},
  example:"A 9-month-old from a rural Anganwadi centre is underweight and cannot sit alone. The interventionist counsels on complementary feeding and shows the mother floor-play on the tummy and supported sitting during daily routines, and refers the child to the DEIC.",
  flags:["Falling across growth centiles or head circumference out of range","Loss of skills already achieved","Delay in two or more domains","Signs of neglect, abuse or severe malnutrition"],
  viva:[["Differentiate growth and development.","Growth is quantitative increase in size; development is qualitative gain in function."],["Who proposed developmental tasks?","Robert Havighurst."],["Give an example of the proximodistal law.","Shoulder control develops before hand and finger control."]],
  refs:[{b:"hurlock",ch:"Principles of development and developmental tasks"},{b:"berk",ch:"History, theory and research strategies; biological and environmental foundations"},{b:"ghai",ch:"Normal growth and development"},{c:"Black MM, Walker SP, Fernald LCH, et al. Early childhood development coming of age: science through the life course. Lancet. 2017;389:77-90.", q:"Black Walker Fernald early childhood development coming of age Lancet"}],
  keywords:"growth development principles laws cephalocaudal proximodistal havighurst tasks nature nurture hazards",
  mcq:[["Head control develops before sitting. This illustrates the:",["Proximodistal law","Cephalocaudal law","Law of individual differences","General to specific law"],1,"Control spreads from head downward."],["Developmental tasks were described by:",["Piaget","Havighurst","Bowlby","Parten"],1,"Havighurst linked tasks to each life period."]]
},
{
  id:"development-theories", title:"Theories of development: psychoanalytic (Freud, Erikson) and Bronfenbrenner's ecological theory", subject:"Early Intervention: Child development", region:"Paper II Child Development", stages:"steps",
  aliases:["Freud psychosexual stages","Erikson psychosocial stages","psychoanalytic theory","Bronfenbrenner ecological systems","microsystem mesosystem","trust vs mistrust"],
  simple:"Freud believed that early childhood experiences, especially how basic needs are met, shape personality. Erikson said that at each age the child faces a social challenge, such as learning to trust. Bronfenbrenner showed that a child grows inside layers of surroundings, from family to community to culture, and all of them matter.",
  flow:["Freud: id, ego, superego and psychosexual stages","Oral, anal, phallic, latency, genital stages","Erikson: eight psychosocial crises across the lifespan","Trust, autonomy and initiative crises fall in early childhood","Bronfenbrenner: micro, meso, exo, macro and chronosystems","Early intervention works on the child and every system"],
  exam:[
    {h:"Introduction", p:["Theories organise observations about development and guide intervention. Psychoanalytic theories focus on inner drives and emotional conflicts; the ecological theory focuses on the environment around the child."]},
    {h:"Freud's psychosexual theory", p:["Personality has three parts: id (pleasure principle, present at birth), ego (reality principle, develops in infancy) and superego (conscience, from about 3-6 years).","Stages: oral (0-1 year, sucking and feeding), anal (1-3 years, toilet training), phallic (3-6 years, Oedipus and Electra conflicts, identification with same-sex parent), latency (6-11 years, energy into school and peers), genital (adolescence).","Too much or too little gratification at a stage can lead to fixation. Criticism: overemphasis on sexual drives, untestable ideas; but it drew attention to the importance of early relationships."]},
    {h:"Erikson's psychosocial theory", p:["Eight stages, each a crisis between a positive and negative outcome: trust vs mistrust (birth-1 year), autonomy vs shame and doubt (1-3), initiative vs guilt (3-6), industry vs inferiority (6-11), identity vs role confusion (adolescence), intimacy vs isolation, generativity vs stagnation, integrity vs despair.","Trust arises from warm, consistent, responsive care; autonomy from being allowed safe choices and self-help; initiative from encouragement to explore and plan play.","Strength: lifespan view and cultural context; criticism: stages are broad and hard to measure."]},
    {h:"Bronfenbrenner's ecological (bioecological) theory", p:["Microsystem: direct settings such as family, Anganwadi, therapy centre. Mesosystem: links between microsystems (parent-teacher, parent-therapist).","Exosystem: settings the child is not in but that affect the child, such as parent's workplace or local health services. Macrosystem: culture, values, laws and policies (RPwD Act 2016, RBSK).","Chronosystem: change over time, such as birth of a sibling, migration or a parent's death. Relationships are bidirectional: the child also shapes the environment."]},
    {h:"Implications for early intervention", p:["Erikson: build trust through predictable routines and responsive caregivers; allow a toddler with a disability to make choices and do self-help tasks rather than doing everything for the child.","Freud: feeding, toileting and early attachment are emotionally loaded; handle feeding and toilet-training difficulties in children with disability calmly and positively.","Bronfenbrenner: intervention cannot stop at the child; strengthen parents, link the family with Anganwadi, school and DEIC (mesosystem), help with disability certificates and schemes (exo and macro), and support families through transitions."]},
    {h:"Conclusion", p:["Psychoanalytic theories explain emotional needs in early childhood; the ecological theory explains why family-centred, community-based early intervention is needed."]}
  ],
  tip:"Draw five concentric circles with the child in the centre labelled micro, meso, exo, macro and an arrow round the outside for chronosystem; add a small table of Erikson's first three stages with ages.",
  evidence:[["Family-centred early intervention (based on ecological and family systems ideas)","Improves parent confidence and child functioning","Moderate"],["Parent-infant psychotherapy (psychoanalytic roots)","May improve infant attachment security; evidence mixed","Weak"],["Home visiting programmes working across child and family systems","Improve parenting and some child outcomes","Moderate"]],
  evidenceSource:"Dunst family-centred practice reviews; Cochrane review of parent-infant psychotherapy (Barlow et al.)",
  outcomes:[["Family needs survey","Needs across family and community systems"],["Observation of caregiver-child interaction","Responsiveness and trust building"],["Developmental assessment (DASII)","Child's level in each domain"]],
  recent:["Bronfenbrenner later renamed his model the bioecological model, adding the process-person-context-time (PPCT) emphasis on proximal processes."],
  mnemonic:{word:"Old Age Pensioners Love Gold", items:[["O","Oral"],["A","Anal"],["P","Phallic"],["L","Latency"],["G","Genital"]], extra:"Erikson's first three: Trust, Autonomy, Initiative (TAI)."},
  example:"A 2-year-old with spina bifida is fed and dressed entirely by his grandmother. The interventionist uses Erikson's autonomy stage to explain why he should be allowed to finger-feed and choose toys, and links the family with the Anganwadi worker and a disability pension scheme, applying Bronfenbrenner's model.",
  flags:["Persistent mistrust: withdrawn infant with no reliable caregiver","Overprotection blocking autonomy in children with disability","Family stress, poverty or violence in the microsystem","Lack of links between home and services"],
  viva:[["What is Erikson's first stage?","Trust vs mistrust, birth to about 1 year."],["What is the mesosystem?","The links between two microsystems, such as home and preschool."],["What is the latency stage?","Freud's stage from about 6 years to puberty when sexual drives are quiet."]],
  refs:[{b:"berk",ch:"Theories of development: psychoanalytic and ecological perspectives"},{b:"hurlock",ch:"Personality development"},{b:"dunst",ch:"Family-centred practice"},{c:"Bronfenbrenner U. The Ecology of Human Development: Experiments by Nature and Design. Cambridge, MA: Harvard University Press; 1979.", q:"Bronfenbrenner ecology of human development"}],
  keywords:"freud psychosexual erikson psychosocial bronfenbrenner ecological theory microsystem",
  mcq:[["Autonomy vs shame and doubt is seen at about:",["Birth-1 year","1-3 years","3-6 years","6-11 years"],1,"Toddlers want to do things for themselves."],["A parent's workplace policy affecting the child belongs to the:",["Microsystem","Mesosystem","Exosystem","Chronosystem"],2,"The child is not in that setting but is affected by it."]]
},
{
  id:"perceptual-development", title:"Sensory-perceptual development: sensation, perception, attention and memory", subject:"Early Intervention: Child development", region:"Paper II Child Development", stages:"steps",
  aliases:["sensation and perception","perceptual development in infancy","visual cliff","depth perception","attention in infants","memory development","habituation"],
  simple:"Sensation is picking up light, sound, touch and taste through the sense organs. Perception is the brain making sense of that information, such as knowing a face is mother's face. Babies are born ready to sense and quickly learn to perceive, pay attention and remember.",
  flow:["Sensation: receptors detect stimuli","Perception: brain organises and interprets sensations","Newborn senses work; vision is the least mature","Depth, face and speech perception develop in first year","Attention and memory grow from habituation to recall","Rich multisensory play supports perceptual growth"],
  exam:[
    {h:"Definitions", p:["Sensation: detection of a stimulus by sense organs and its transmission to the brain.","Perception: organisation and interpretation of sensations into meaningful experience; depends on maturation and learning.","Perceptual development: the progressive refinement of the ability to interpret sensory information."]},
    {h:"Sensory abilities of the newborn", p:["Touch: well developed; responds to pain and is soothed by holding. Taste and smell: prefers sweet, recognises mother's milk smell within days.","Hearing: hears at birth, prefers human voice and mother's voice.","Vision: least mature; acuity is poor, focuses best at about 20-30 cm, prefers faces and high contrast; acuity and colour vision improve rapidly over the first months."]},
    {h:"Perceptual development in infancy", p:["Depth perception: Gibson and Walk's visual cliff showed crawling infants (about 6 months and older) avoid the deep side.","Pattern and face perception: preference for faces early, recognition of mother's face within the first months.","Speech perception: infants discriminate speech sounds of all languages and narrow to their native language by about 10-12 months.","Intermodal perception: linking sight, sound and touch of the same event; object permanence and size and shape constancy develop over the first year."]},
    {h:"Factors in the perceptual process: attention and memory", p:["Attention: selection of some stimuli for processing; infants move from reflexive orienting to voluntary, sustained attention; joint attention appears around 9-12 months.","Memory: habituation (reduced response to a repeated stimulus) shows recognition memory from birth; recall memory and deferred imitation develop by the end of the first year; working memory grows through early childhood.","Other factors: sensory integrity, maturation, motivation, past experience, culture and emotional state."]},
    {h:"Assessment and early intervention", p:["Screen hearing (newborn OAE or BERA in high-risk infants) and vision (red reflex, fixation and following) early; refer if not tracking a face by about 3 months or no startle to sound.","Home activities: face-to-face talking at 20-30 cm, high-contrast cards, rattles to track, varied textures, naming objects during bathing and feeding, peek-a-boo for memory and object permanence.","For children with sensory impairment, use the remaining senses intensively and fit aids or spectacles as early as possible."]},
    {h:"Conclusion", p:["Perception, attention and memory are the gateway to learning; early detection of sensory loss and a stimulating home lay the base for cognition and language."]}
  ],
  tip:"Draw a flow box: stimulus to receptor (sensation) to brain interpretation (perception) to attention filter to memory store; sketch the visual cliff as a table with a glass top over a drop.",
  evidence:[["Universal newborn hearing screening with early amplification","Better language outcomes when identified early","Strong"],["Early cataract and refractive correction","Prevents amblyopia and supports visual development","Strong"],["Sensory stimulation programmes in preterm infants","Small short-term benefits; long-term effect unclear","Weak"]],
  evidenceSource:"Joint Committee on Infant Hearing 2019 position statement; Berk infant perception chapter",
  outcomes:[["OAE and BERA","Hearing screening and threshold"],["Red reflex and fixation-following","Basic vision screen"],["DASII mental scale","Includes attention and object permanence items"]],
  recent:["Joint Committee on Infant Hearing 2019 position statement reaffirms the 1-3-6 benchmark: screen by 1 month, diagnose by 3 months, intervene by 6 months."],
  mnemonic:{word:"SPAM", items:[["S","Sensation"],["P","Perception"],["A","Attention"],["M","Memory"]], extra:"Habituation is the infant's first proof of memory."},
  example:"A 4-month-old born at 30 weeks does not fix on her mother's face. The interventionist refers her for ROP and vision assessment and teaches the mother to hold her close, talk face to face and use black-and-white cards during awake times.",
  flags:["No fixation or following of a face by 3 months","No startle or turning to sound","Roving or wandering eye movements, white pupil","Preterm infant without ROP screening"],
  viva:[["Differentiate sensation and perception.","Sensation is detection; perception is interpretation."],["What did the visual cliff test?","Depth perception in crawling infants."],["What is habituation?","Decreasing response to a repeated stimulus, showing recognition memory."]],
  refs:[{b:"berk",ch:"Perceptual development in infancy"},{b:"hurlock",ch:"Sensory and perceptual development"},{b:"bundy",ch:"Sensory integration theory"},{c:"Joint Committee on Infant Hearing. Year 2019 position statement: principles and guidelines for early hearing detection and intervention programs. J Early Hear Detect Interv. 2019;4(2):1-44.", q:"Joint Committee on Infant Hearing 2019 position statement"}],
  keywords:"sensation perception perceptual development attention memory visual cliff habituation",
  mcq:[["The visual cliff experiment studied:",["Colour vision","Depth perception","Hearing","Object permanence"],1,"Gibson and Walk, 1960."],["Reduced response to a repeated stimulus is called:",["Sensitisation","Habituation","Accommodation","Assimilation"],1,"It shows recognition memory."]]
},
{
  id:"motor-development", title:"Motor development: principles, sequence, motor skills and handedness", subject:"Early Intervention: Child development", region:"Paper II Child Development", stages:"steps",
  aliases:["gross motor development","fine motor development","sequence of motor development","prehension","handedness","hand dominance"],
  simple:"Motor development is how a baby gains control of body movement, from lifting the head to running and drawing. It follows the same order in almost all children, though timing varies. Hand preference settles in the preschool years.",
  flow:["Reflex movements give way to voluntary control","Head control, rolling, sitting, crawling, standing, walking","Grasp moves from palmar to pincer","Gross skills refine into running, jumping, hopping","Hand preference emerges and stabilises by 4-6 years","Practice in play strengthens every motor skill"],
  exam:[
    {h:"Definition", p:["Motor development: progressive change in movement behaviour, from reflexes to coordinated voluntary skills, through maturation of the nervous and musculoskeletal systems and practice.","Gross motor skills use large muscles (sitting, walking, jumping); fine motor skills use small muscles of the hand (grasp, release, drawing)."]},
    {h:"Principles of motor development", p:["Depends on neural and muscular maturation; skills cannot be taught before the child is ready.","Follows cephalocaudal and proximodistal laws; moves from mass to specific and from gross to fine.","Sequence is predictable though the rate varies; practice and opportunity refine skills; early skills form the base for later ones.","Dynamic systems view: motor skills emerge from the interaction of body, task and environment, not maturation alone."]},
    {h:"Sequence of gross and fine motor development (approximate ages)", p:["Gross: head control 3-4 months, rolling 4-6, sitting alone 6-8, crawling 8-10, pulling to stand 9-10, walking 12-15 months, running 18 months-2 years, stairs alone 2-3 years, hopping 4 years, skipping 5 years.","Fine: grasp reflex at birth, hands at midline 3-4 months, palmar grasp and transfer 5-6 months, inferior then neat pincer 9-12 months, tower of 2-3 cubes 15-18 months, scribbles 15-18 months, copies circle 3 years, cross 4 years, square 4-5 years, triangle 5 years."]},
    {h:"Characteristics of motor development and handedness", p:["Motor skills improve in speed, accuracy, steadiness and economy; boys and girls are similar in early years.","Handedness: preference shifts in infancy; a consistent preference usually develops by about 2-3 years and becomes stable by 4-6 years. Most children are right-handed.","A clear hand preference before about 12-18 months is abnormal and may signal weakness of the other hand (for example hemiplegic cerebral palsy or brachial plexus injury).","Left-handed children should not be forced to switch; seat and set up writing materials to suit them."]},
    {h:"Assessment and early intervention", p:["Observe posture, movement quality and milestone ages; tools include TDSC for screening, DASII motor scale, Peabody Developmental Motor Scales, Alberta Infant Motor Scale and, in high-risk infants, General Movements Assessment and HINE.","Home activities: tummy time while awake, reaching for toys at midline, supported sitting with toys, cruising along furniture, ball play, stacking cups, tearing paper, scribbling with thick crayons.","Teach parents to give practice within daily routines and to avoid baby walkers, which do not help walking and cause injuries."]},
    {h:"Conclusion", p:["Motor development opens up exploration that feeds cognitive, social and language growth; early detection of delayed or atypical movement allows timely therapy."]}
  ],
  tip:"Draw a staircase of gross motor milestones from 3 to 24 months on one side and a row of hand sketches (palmar, radial-palmar, pincer) on the other.",
  evidence:[["Early diagnosis of CP with GMA and HINE","Allows intervention before 6 months corrected age","Strong"],["Task-specific, child-active motor training in CP","Improves motor function","Strong"],["Baby walkers","No benefit for walking; risk of injury","Moderate"]],
  evidenceSource:"Novak et al. 2017 JAMA Pediatrics; Novak et al. 2020 Current Neurology and Neuroscience Reports; AAP injury prevention statements on baby walkers",
  outcomes:[["Alberta Infant Motor Scale","Gross motor 0-18 months"],["Peabody Developmental Motor Scales","Gross and fine motor 0-5 years"],["HINE","Neurological examination 2-24 months"]],
  recent:["Novak et al. (JAMA Pediatrics 2017) recommend diagnosing or flagging high risk of CP before 6 months corrected age using MRI, GMA and HINE."],
  mnemonic:{word:"Circle-Cross-Square-Triangle 3-4-4.5-5", items:[["3","Circle"],["4","Cross"],["4.5","Square"],["5","Triangle"]], extra:"Gross: 3 head, 6 sit, 9 crawl, 12 walk."},
  example:"A 10-month-old reaches only with her right hand and keeps the left fisted. The interventionist flags early handedness as a warning sign, refers for neurological review, and starts bimanual play such as holding a big ball with both hands.",
  flags:["Hand preference before 12 months","Not sitting by 9 months or not walking by 18 months","Persistent fisting, asymmetry or stiffness","Loss of motor skills"],
  viva:[["When is pincer grasp seen?","About 9-12 months."],["When is hand dominance established?","Usually stable by 4-6 years."],["Why is early handedness a concern?","It may indicate weakness of the other side, as in hemiplegia."]],
  refs:[{b:"caseSmith",ch:"Development of hand skills"},{b:"campbell",ch:"Motor development and control"},{b:"hurlock",ch:"Motor development"},{c:"Novak I, Morgan C, Adde L, et al. Early, accurate diagnosis and early intervention in cerebral palsy: advances in diagnosis and treatment. JAMA Pediatr. 2017;171(9):897-907.", q:"Novak early accurate diagnosis cerebral palsy JAMA Pediatr 2017"}],
  keywords:"motor development gross fine motor skills sequence handedness prehension",
  mcq:[["A child normally copies a circle at about:",["18 months","3 years","5 years","6 years"],1,"Cross at 4, square about 4-5, triangle 5."],["Clear hand preference at 8 months suggests:",["Gifted motor skill","Possible weakness of the other hand","Normal left-handedness","Visual impairment"],1,"Early handedness is a red flag for hemiplegia or plexus injury."]]
},
{
  id:"cognitive-development", title:"Cognitive development: Piaget, Vygotsky and information processing", subject:"Early Intervention: Child development", region:"Paper II Child Development", stages:"steps",
  aliases:["Piaget stages","sensorimotor stage","object permanence","Vygotsky ZPD","scaffolding","information processing","cognition and language"],
  simple:"Cognition means thinking, understanding, remembering and problem solving. Piaget said children build knowledge by exploring, passing through stages. Vygotsky said children learn best with help from a more skilled person, just beyond what they can do alone.",
  flow:["Cognition: thinking, reasoning, memory, problem solving","Piaget: schemas adapt by assimilation and accommodation","Sensorimotor, preoperational, concrete, formal operational stages","Vygotsky: social learning, ZPD and scaffolding","Information processing: attention, memory, speed, strategies","Play and talk at home build cognition and language"],
  exam:[
    {h:"Concept and definition", p:["Cognitive development: growth of mental processes by which a child acquires, stores, transforms and uses knowledge, including perception, attention, memory, reasoning, concept formation and problem solving.","Factors: brain maturation, nutrition (iodine, iron), health, sensory integrity, stimulation, parental education, socio-economic status, culture and play opportunities."]},
    {h:"Piaget's theory", p:["Key ideas: schema (organised pattern of thought or action), adaptation by assimilation (fitting new experience into an existing schema) and accommodation (changing the schema), equilibration.","Sensorimotor (0-2 years): learning through senses and action; six substages from reflexes to mental representation; object permanence develops (searching for hidden toy from about 8-12 months), circular reactions, deferred imitation.","Preoperational (2-7 years): symbolic and pretend play, language; egocentrism, centration, animism, lack of conservation.","Concrete operational (7-11 years): conservation, classification, seriation, logical thought about concrete things. Formal operational (11 years on): abstract and hypothetical reasoning.","Criticism: underestimated infants, stages less rigid than he proposed, little attention to culture."]},
    {h:"Vygotsky's sociocultural theory", p:["Learning happens first between people and is then internalised; culture and language are tools of thought.","Zone of proximal development (ZPD): the gap between what a child can do alone and what the child can do with guidance.","Scaffolding: adult support adjusted to the child's level and gradually withdrawn as competence grows.","Private speech: children talk to themselves to guide action, which later becomes inner speech."]},
    {h:"Information processing approach, and cognition and language", p:["Views the mind like a computer: input through sensory register, working memory with limited capacity, long-term memory; development is growth in capacity, speed, attention control and use of strategies (rehearsal, organisation), and executive function.","Cognition and language: Piaget held that thought comes first and language reflects it; Vygotsky held that they start separately and merge around 2 years, when speech becomes a tool for thinking.","Language delay limits access to learning, and poor cognitive skills limit language; they must be assessed together."]},
    {h:"Assessment and early intervention", p:["Tools: DASII mental scale, Bayley Scales, MDPS and Upanayan checklists for teaching goals, Portage Guide to Early Education for home teaching.","Home activities: hide a toy under a cloth (object permanence), cause-effect toys, shape sorters, pretend play with kitchen items, sorting by colour, naming during routines.","Use scaffolding: show, help hand-over-hand, then reduce help; set goals inside the ZPD using a task analysis."]},
    {h:"Conclusion", p:["Piaget explains what children can understand at each stage, Vygotsky how adults help them move forward, and information processing how capacities grow; all three guide early intervention planning."]}
  ],
  tip:"Draw a four-step staircase of Piaget's stages with ages; beside it draw three nested circles for Vygotsky: can do alone, ZPD (can do with help), cannot do yet.",
  evidence:[["Responsive parenting and early stimulation programmes","Improve cognitive outcomes in young children","Strong"],["Early intervention for preterm infants","Improves cognitive outcomes in infancy and preschool years; less clear at school age","Moderate"],["Portage home teaching","Gains in developmental skills reported; trials are small","Weak"]],
  evidenceSource:"Spittle et al. Cochrane review of early developmental intervention for preterm infants; Lancet ECD Series 2016",
  outcomes:[["DASII mental scale","Cognitive developmental quotient 0-30 months"],["Bayley Scales of Infant and Toddler Development","Cognitive, language and motor"],["Portage checklist","Cognitive and self-help skills achieved"]],
  recent:["Spittle et al. updated Cochrane review (2015) found early developmental interventions after hospital discharge improve cognitive outcomes in preterm infants at infant and preschool ages."],
  mnemonic:{word:"SPCF", items:[["S","Sensorimotor 0-2"],["P","Preoperational 2-7"],["C","Concrete operational 7-11"],["F","Formal operational 11+"]], extra:"Vygotsky: ZPD is the zone, scaffolding is the support."},
  example:"A 2-year-old with Down syndrome cannot find a toy hidden under a cloth. The mother is shown to half-cover the toy first, praise the search, then fully cover it, scaffolding object permanence within the ZPD.",
  flags:["No interest in faces or toys by 6 months","No pretend play by 2 years","Regression of skills","Poor response to name and to simple instructions"],
  viva:[["What is object permanence?","Knowing an object exists when it cannot be seen; develops in the sensorimotor stage."],["Define ZPD.","The gap between independent performance and performance with help."],["What is accommodation?","Changing a schema to fit new information."]],
  refs:[{b:"berk",ch:"Cognitive development: Piagetian, sociocultural and information-processing perspectives"},{b:"hurlock",ch:"Understanding and concept development"},{b:"batshaw",ch:"Intellectual disability and developmental assessment"},{c:"Spittle A, Orton J, Anderson PJ, Boyd R, Doyle LW. Early developmental intervention programmes provided post hospital discharge to prevent motor and cognitive impairment in preterm infants. Cochrane Database Syst Rev. 2015;(11):CD005495.", q:"Spittle early developmental intervention preterm infants Cochrane"}],
  keywords:"cognitive development piaget vygotsky zpd scaffolding information processing object permanence",
  mcq:[["Object permanence develops in which Piagetian stage?",["Sensorimotor","Preoperational","Concrete operational","Formal operational"],0,"It emerges in the second half of the first year."],["Adult help that is gradually withdrawn is called:",["Assimilation","Scaffolding","Centration","Habituation"],1,"A Vygotskian idea."]]
},
{
  id:"social-development", title:"Social development and socialization", subject:"Early Intervention: Child development", region:"Paper II Child Development", stages:"steps",
  aliases:["socialization","agents of socialization","social smile","stranger anxiety","peer relations","social behaviour patterns"],
  simple:"Social development is how a child learns to get along with other people and follow the ways of the family and community. It starts with the baby's first smile and grows through play with family, friends and school. Parents, siblings, peers, school, media and culture all teach the child how to behave.",
  flow:["Infant responds to faces and smiles socially","Stranger anxiety and attachment by 6-9 months","Toddler imitates, plays alongside other children","Preschooler shares, cooperates, follows rules","Agents: family, peers, school, media, culture","Interventionist builds social skills in daily routines"],
  exam:[
    {h:"Concept and meaning", p:["Social development: acquiring the ability to behave in accordance with social expectations, to relate to others and to take part in group life.","Socialization: the lifelong process by which a child learns the values, norms, roles and behaviour of the society."]},
    {h:"Course and characteristics of social development", p:["Infancy: social smile about 6-8 weeks, recognises familiar people about 3-4 months, stranger anxiety about 6-9 months, joint attention and waving about 9-12 months.","Toddler: imitates adults, parallel play, possessive, beginnings of turn-taking, negativism common around 2 years.","Preschool: associative and cooperative play, friendships, sharing, empathy, sex-role learning, following simple rules.","Hurlock's patterns: social behaviour such as imitation, rivalry, cooperation, sympathy, empathy, generosity and dependency; unsocial patterns such as quarrelling, teasing and aggression.","Development is sequential, influenced by early experience, and closely linked with emotional and language development."]},
    {h:"Process and agents of socialization", p:["Processes: imitation, identification, reward and punishment, observational learning, instruction.","Family: first and most important agent; parenting style, siblings and grandparents in Indian joint families.","Peers, Anganwadi and preschool, school, neighbourhood, religious and cultural groups, and mass media and screens.","Primary socialization (family) in early years; secondary socialization (school, peers, society) later."]},
    {h:"Assessment and early intervention", p:["Observe eye contact, social smile, response to name, joint attention, imitation and play with peers; screen with M-CHAT-R/F at 18-24 months when autism is a concern, and use DASII and Portage socialization items.","Home activities: face-to-face games, peek-a-boo, turn-taking with a ball, songs with actions, playing with cousins and neighbours, involving the child in family meals and festivals.","For children with disability, reduce isolation, arrange inclusive play groups at the Anganwadi, and teach siblings simple ways to play with the child."]},
    {h:"Conclusion", p:["Social skills are learned, not inborn; the family is the first teacher, and early support prevents isolation and later behaviour problems."]}
  ],
  tip:"Draw the child in the centre with spokes to family, peers, school, community, media and culture labelled as agents of socialization.",
  evidence:[["Parent-mediated social communication intervention in autism","Improves parent-child interaction; child social outcomes modest","Moderate"],["High-quality preschool and early education","Improves social and school readiness","Moderate"],["Social skills groups for young children","Mixed, small effects","Weak"]],
  evidenceSource:"Green et al. PACT trial (Lancet 2010); Berk and Hurlock chapters on social development",
  outcomes:[["Vineland Adaptive Behavior Scales","Socialization and adaptive behaviour"],["M-CHAT-R/F","Autism screening 16-30 months"],["Portage socialization checklist","Social skills achieved"]],
  recent:["Pickles et al. (Lancet 2016) reported that the PACT parent-mediated intervention for autism had sustained effects on symptom severity about six years later."],
  mnemonic:{word:"FPS-MCN", items:[["F","Family"],["P","Peers"],["S","School"],["M","Media"],["C","Culture and religion"],["N","Neighbourhood"]], extra:"Smile at 6 weeks, stranger anxiety at 6-9 months."},
  example:"A 20-month-old boy rarely looks at his parents and does not respond to his name. The interventionist screens with M-CHAT-R/F, refers for diagnostic assessment and starts turn-taking games and imitation at bath and meal times.",
  flags:["No social smile by 3 months","No response to name or joint attention by 12 months","Loss of social skills or words","Persistent aggression or withdrawal"],
  viva:[["When does stranger anxiety appear?","About 6-9 months."],["Name the primary agent of socialization.","The family."],["Define socialization.","Learning the values and behaviour expected by society."]],
  refs:[{b:"hurlock",ch:"Social development"},{b:"berk",ch:"Emotional and social development in early childhood"},{b:"turnbull",ch:"Families and community participation"},{c:"Green J, Charman T, McConachie H, et al. Parent-mediated communication-focused treatment in children with autism (PACT): a randomised controlled trial. Lancet. 2010;375:2152-60.", q:"Green Charman PACT parent-mediated autism Lancet 2010"}],
  keywords:"social development socialization agents family peers social smile stranger anxiety",
  mcq:[["The social smile usually appears at about:",["Birth","6-8 weeks","6 months","1 year"],1,"An early social milestone."],["The most important agent of primary socialization is:",["School","Media","Family","Peers"],2,"The family teaches the first social rules."]]
},
{
  id:"emotional-development", title:"Emotional development: components, patterns, theories and emotional deprivation", subject:"Early Intervention: Child development", region:"Paper II Child Development", stages:"steps",
  aliases:["components of emotion","common emotional patterns","James-Lange theory","Cannon-Bard theory","emotional deprivation","temper tantrums"],
  simple:"An emotion is a feeling such as joy, fear or anger, with body changes and an urge to act. Babies show basic emotions early and learn more complex ones like shame and pride by 2-3 years. Children who do not get love and attention can suffer emotional deprivation, which harms growth and learning.",
  flow:["Emotion: feeling, body change, expression, action","Basic emotions early; self-conscious emotions by 2-3 years","Common patterns: fear, anger, joy, jealousy, affection","James-Lange: body change comes before feeling","Cannon-Bard: body change and feeling occur together","Deprivation of love harms growth, language and behaviour"],
  exam:[
    {h:"Definition and components of emotion", p:["Emotion: a state of arousal with a subjective feeling, physiological change and an expressive and behavioural response.","Components: (1) cognitive appraisal of the situation, (2) subjective feeling, (3) physiological arousal through the autonomic nervous system, (4) expression in face, voice and posture, (5) action tendency such as approach or flight.","Emotions in children are brief, intense, frequent, transitory and shown openly; they change in strength and can be detected through behaviour (Hurlock)."]},
    {h:"Development and common emotional patterns", p:["Distress and contentment at birth; social smile about 6-8 weeks; anger, sadness and fear (stranger anxiety) by about 6-9 months; shame, guilt, pride and jealousy appear about 18-36 months with self-awareness.","Common patterns: fear (dark, animals, strangers), shyness, anger and temper tantrums (peak about 2-4 years), jealousy (new sibling), curiosity, joy, affection, grief and envy.","Emotional regulation grows from caregiver soothing to self-soothing and use of language for feelings."]},
    {h:"Theories of emotion", p:["James-Lange theory: a stimulus causes bodily changes, and awareness of these changes is the emotion (we feel afraid because we tremble).","Cannon-Bard theory: the thalamus sends signals at the same time to the cortex (feeling) and to the body (arousal), so feeling and bodily change occur together and independently.","Criticism of James-Lange: different emotions show similar bodily arousal; Cannon-Bard gave the brain a central role. Later appraisal theories add the role of thinking."]},
    {h:"Emotional deprivation", p:["Lack of warm, consistent affection and stimulation, as in neglect, prolonged hospitalisation, institutional care or depressed caregivers.","Effects: failure to thrive and psychosocial short stature, delayed motor, language and cognitive development, apathy or indiscriminate friendliness, attachment disorders and later behaviour problems.","Studies of children in deprived institutions show that the earlier the child is placed in a responsive family, the better the recovery."]},
    {h:"Assessment and early intervention", p:["Observe the infant's affect, soothability, responsiveness and caregiver interaction; screen the mother for postnatal depression.","Home activities: responsive talking and touch, kangaroo care for preterm infants, naming feelings, calm routines, emotion picture books and puppet play, a quiet corner for tantrums.","For tantrums, teach parents to stay calm, ignore safe attention-seeking, praise calm behaviour and avoid harsh punishment; refer for counselling when the family is in crisis."]},
    {h:"Conclusion", p:["Emotional security is the base for learning and social life; early, responsive care prevents deprivation and helps children with disability handle frustration."]}
  ],
  tip:"Draw two flow diagrams side by side. James-Lange: stimulus to body change to feeling. Cannon-Bard: stimulus to thalamus, then two arrows, one to the cortex (feeling) and one to the body (arousal).",
  evidence:[["Kangaroo mother care","Improves bonding and reduces mortality in low birth weight infants","Strong"],["Early foster placement after institutional care","Better cognitive and emotional recovery than remaining in institution","Strong"],["Parenting programmes for toddler behaviour","Reduce behaviour problems","Moderate"]],
  evidenceSource:"Bucharest Early Intervention Project (Nelson, Zeanah, Fox); Cochrane review of kangaroo mother care (Conde-Agudelo and Diaz-Rossello 2016)",
  outcomes:[["Edinburgh Postnatal Depression Scale","Maternal depression screen"],["Ages and Stages Questionnaire: Social-Emotional","Social-emotional screening"],["Observation of caregiver-infant interaction","Warmth and responsiveness"]],
  recent:["The Bucharest Early Intervention Project, a randomised trial of foster care versus continued institutional care, showed better outcomes with earlier placement."],
  mnemonic:{word:"CSPEA", items:[["C","Cognitive appraisal"],["S","Subjective feeling"],["P","Physiological arousal"],["E","Expression"],["A","Action tendency"]], extra:"James-Lange: body first. Cannon-Bard: both at once."},
  example:"A 14-month-old girl in a children's home is underweight, rarely smiles and shows little interest in toys. The team arranges a consistent caregiver, daily play sessions and nutritional support, and starts the process for family-based care.",
  flags:["Flat affect, no social smile, failure to thrive","Indiscriminate friendliness with strangers","Severe or self-injurious tantrums","Signs of abuse or maternal depression"],
  viva:[["State the James-Lange theory.","Bodily change comes first, and the feeling is the awareness of that change."],["Which brain part did Cannon-Bard stress?","The thalamus."],["Name two effects of emotional deprivation.","Failure to thrive and delayed language or attachment problems."]],
  refs:[{b:"hurlock",ch:"Emotional development"},{b:"berk",ch:"Emotional development in infancy and toddlerhood"},{b:"nelson",ch:"Failure to thrive and psychosocial issues"},{c:"Nelson CA, Zeanah CH, Fox NA, et al. Cognitive recovery in socially deprived young children: the Bucharest Early Intervention Project. Science. 2007;318:1937-40.", q:"Nelson Zeanah Fox Bucharest Early Intervention Project Science 2007"}],
  keywords:"emotional development emotion components james lange cannon bard emotional deprivation tantrums",
  mcq:[["According to Cannon-Bard theory, emotional feeling and bodily arousal:",["Occur together","Body change comes first","Feeling comes first","Are both caused by the cortex alone"],0,"The thalamus signals both simultaneously."],["Self-conscious emotions such as shame appear at about:",["Birth","3 months","18-36 months","6 years"],2,"They need self-awareness."]]
},
{
  id:"attachment-parenting", title:"Attachment, bonding, family influences and parenting styles", subject:"Early Intervention: Child development", region:"Paper II Child Development", stages:"steps",
  aliases:["Bowlby attachment","Ainsworth strange situation","mother-infant interaction","Baumrind parenting styles","child rearing practices","sibling relationships","parental attitudes"],
  simple:"Attachment is the strong emotional tie a baby forms with the people who care for it. Babies whose caregivers respond warmly and consistently become securely attached and explore with confidence. The way parents bring up a child, how warm and how firm they are, shapes the child's behaviour and development.",
  flow:["Bonding: parent's tie to the newborn","Attachment: infant's tie to caregiver, built over the first year","Ainsworth: secure, avoidant, resistant, disorganized","Family, siblings, home and parental attitudes shape development","Baumrind: authoritative, authoritarian, permissive, uninvolved","Coach responsive, warm and firm parenting"],
  exam:[
    {h:"Definitions", p:["Bonding: the emotional tie of the parent to the infant, often beginning in pregnancy and the early postnatal period.","Attachment: the enduring emotional tie of the infant to a caregiver, shown by seeking closeness, especially when distressed."]},
    {h:"Bowlby and Ainsworth", p:["Bowlby's ethological theory: attachment is an evolved system for safety. Phases: pre-attachment (0-6 weeks), attachment in the making (6 weeks-6 to 8 months), clear-cut attachment (6-8 months to 18-24 months, separation anxiety), formation of a reciprocal relationship (after 18-24 months). The child builds an internal working model of relationships.","Ainsworth's Strange Situation (12-18 months) classifies: secure (upset at separation, comforted at reunion), insecure-avoidant (ignores mother), insecure-resistant or ambivalent (clings yet resists comfort); Main and Solomon added disorganized-disoriented.","Secure base: the caregiver from which the child explores. Sensitive, responsive caregiving predicts secure attachment."]},
    {h:"Mother-infant interaction, family and home", p:["Serve and return: the infant signals by crying, cooing or gaze, and the caregiver responds contingently; this builds attachment, language and emotional regulation.","Family relationships: marital harmony, father's involvement and joint family support all influence the child; conflict and stress harm development.","Siblings: companions, teachers and rivals; jealousy at a new birth is common; siblings of a child with disability may need attention and information.","Home environment: safe space, toys and books, talk and routines (measured by the HOME inventory)."]},
    {h:"Parental attitudes, child-rearing practices and parenting styles", p:["Attitudes: acceptance, overprotection, rejection, over-indulgence, perfectionism, denial; parents of a child with disability may pass through shock, denial, guilt and acceptance.","Indian practices: co-sleeping, prolonged breastfeeding, oil massage, joint family care, late toilet training, and in some homes harsh discipline or gender preference.","Baumrind: authoritative (high warmth, high control, explains rules) leads to the best competence; authoritarian (low warmth, high control) to anxious or withdrawn behaviour; permissive (high warmth, low control) to poor self-control. Maccoby and Martin added uninvolved or neglectful (low on both), with the worst outcomes."]},
    {h:"Implications and early intervention", p:["Normal development: secure attachment and authoritative parenting support confidence, exploration, language and social skill.","Abnormal development: neglect, rejection and harsh discipline lead to insecure or disordered attachment, behaviour problems and delay; a child's disability, prematurity or NICU stay can disturb early interaction and bonding.","Intervention: rooming-in, kangaroo care, coaching parents to read infant cues and respond, video feedback, counselling for guilt and grief, involving fathers and siblings, and linking to parent support groups and National Trust schemes."]},
    {h:"Conclusion", p:["The parent-child relationship is the main channel of early intervention; strengthening it benefits every domain of development."]}
  ],
  tip:"Draw a 2x2 grid with warmth on one axis and control on the other, placing authoritative, authoritarian, permissive and uninvolved in the four boxes; add a small Strange Situation flow (mother leaves, stranger, mother returns).",
  evidence:[["Attachment-based video-feedback interventions","Increase parental sensitivity","Moderate"],["Kangaroo care and rooming-in","Support bonding and breastfeeding","Strong"],["Group parenting programmes for behaviour","Improve parenting and reduce child behaviour problems","Moderate"]],
  evidenceSource:"Bakermans-Kranenburg et al. meta-analysis of sensitivity and attachment interventions (Psychol Bull 2003); Cochrane parenting programme reviews",
  outcomes:[["Strange Situation Procedure","Attachment classification at 12-18 months"],["HOME inventory","Quality of home environment"],["Parenting Stress Index","Parental stress"]],
  recent:["Bakermans-Kranenburg, van IJzendoorn and Juffer (2003) found that short, focused interventions on parental sensitivity were the most effective at improving sensitivity and attachment."],
  mnemonic:{word:"SARD", items:[["S","Secure"],["A","Avoidant"],["R","Resistant (ambivalent)"],["D","Disorganized"]], extra:"Authoritative = warm + firm = best outcome."},
  example:"After 6 weeks in the NICU, a mother of a preterm baby with Down syndrome avoids holding him. The interventionist uses kangaroo care, shows her his cues of engagement and stress, counsels her on guilt and connects her with a parent support group.",
  flags:["Infant does not seek or accept comfort","Caregiver rejecting, depressed or using harsh punishment","Signs of neglect or abuse","Severe parental stress after diagnosis of disability"],
  viva:[["Who devised the Strange Situation?","Mary Ainsworth."],["Which parenting style gives the best outcomes?","Authoritative: warm and firm."],["Differentiate bonding and attachment.","Bonding is parent to infant; attachment is infant to caregiver."]],
  refs:[{b:"berk",ch:"Attachment and parenting"},{b:"turnbull",ch:"Family interaction and family functions"},{b:"hurlock",ch:"Family relationships"},{c:"Bakermans-Kranenburg MJ, van IJzendoorn MH, Juffer F. Less is more: meta-analyses of sensitivity and attachment interventions in early childhood. Psychol Bull. 2003;129(2):195-215.", q:"Bakermans-Kranenburg less is more sensitivity attachment interventions meta-analysis"}],
  keywords:"attachment bonding bowlby ainsworth strange situation baumrind parenting styles family siblings home child rearing",
  mcq:[["High warmth and high control describes which style?",["Authoritarian","Authoritative","Permissive","Uninvolved"],1,"Associated with best child outcomes."],["An infant who ignores the mother on reunion is classified as:",["Secure","Insecure-avoidant","Resistant","Disorganized"],1,"Avoidant infants show little response to reunion."]]
},
{
  id:"play-development", title:"Play: definition, components, types, stages and influence on development", subject:"Early Intervention: Child development", region:"Paper II Child Development", stages:"steps",
  aliases:["Parten stages of play","types of play","Piaget play stages","pretend play","play therapy","play in children with disabilities"],
  simple:"Play is any activity a child does for fun, by choice, for its own sake. Through play children move, think, talk, make friends and express feelings. Play changes from playing alone to playing together with rules as the child grows.",
  flow:["Play: voluntary, enjoyable, intrinsically motivated activity","Components: motivation, control, reality suspension, process","Piaget: functional, symbolic, games with rules","Parten: unoccupied, solitary, onlooker, parallel, associative, cooperative","Play builds motor, cognitive, language, social, emotional skills","Adapt toys and play for children with disabilities"],
  exam:[
    {h:"Definition", p:["Play: an activity freely chosen, intrinsically motivated, pleasurable and focused on the process rather than the end product (Hurlock describes it as any activity engaged in for the enjoyment it gives, without regard to the result).","Play is the main occupation of childhood and a natural medium for learning and therapy."]},
    {h:"Components of play", p:["Intrinsic motivation, internal control (child decides), freedom to suspend reality (pretend), active engagement and enjoyment (Bundy's playfulness: motivation, control, suspension of reality and framing or reading cues).","Elements of a play environment: space, time, materials or toys, and a playmate or responsive adult."]},
    {h:"Types and stages of play", p:["Piaget: functional or practice play (sensorimotor, 0-2 years, repeating actions), symbolic or pretend play (about 2-7 years), games with rules (about 7-11 years); constructive play (building) spans these.","Parten's social stages: unoccupied, solitary (to about 2 years), onlooker, parallel (about 2-3 years), associative (about 3-4 years), cooperative (about 4 years and above).","Other types: physical or rough-and-tumble, exploratory, constructive, dramatic, creative (art, music), language play, and traditional Indian games."]},
    {h:"Influence of play on development", p:["Motor: running, climbing, manipulation; cognitive: problem solving, cause-effect, symbolic thought; language: naming and storytelling in pretend play.","Social: sharing, turn-taking, cooperation; emotional: expressing and managing feelings, reducing anxiety, building confidence.","Play deprivation leads to poorer social, emotional and cognitive skills."]},
    {h:"Play for children with disabilities and early intervention", p:["Barriers: motor limits, sensory loss, limited exploration, overprotection, lack of adapted toys and exclusion by peers.","Adaptations: positioning (side-lying, supported sitting), big or textured toys, switch toys, sound or light toys for visual impairment, visual cues for hearing impairment, low-cost toys from household items.","Use play as therapy: follow the child's lead, model and expand, use the Portage and MDPS play goals, and organise inclusive play at the Anganwadi or toy library; assess play with observation or tools such as the Test of Playfulness.","Teach parents simple daily play: water play during bathing, pot-and-spoon music, hide and seek, pretend kitchen."]},
    {h:"Conclusion", p:["Play is both a right of every child and the most natural medium of early intervention; adapting play ensures children with disability do not miss its benefits."]}
  ],
  tip:"Draw a staircase of Parten's six stages with approximate ages, and next to it a three-box arrow for Piaget: functional, symbolic, games with rules.",
  evidence:[["Play-based, parent-mediated early intervention","Improves engagement and communication in young children with autism","Moderate"],["Pretend play training","Improves play skills; effects on wider development are less certain","Weak"],["Play as a context for motor training in CP","Increases practice and participation","Expert opinion"]],
  evidenceSource:"Bundy play and playfulness research; Lillard et al. 2013 review of pretend play (Psychol Bull)",
  outcomes:[["Test of Playfulness","Playfulness in free play"],["Knox Preschool Play Scale","Developmental level of play"],["Portage socialization and cognitive items","Play skills achieved"]],
  recent:["The UN Committee on the Rights of the Child issued General Comment No. 17 (2013) on the child's right to play under Article 31."],
  mnemonic:{word:"U-SOP-AC", items:[["U","Unoccupied"],["S","Solitary"],["O","Onlooker"],["P","Parallel"],["A","Associative"],["C","Cooperative"]], extra:"Piaget: Function, Symbol, Rules."},
  example:"A 3-year-old with spastic diplegia plays only alone with a mobile phone. The interventionist places him in supported sitting at floor level with peers at the Anganwadi, gives a large ball and blocks, and coaches the teacher to start parallel then associative play.",
  flags:["No interest in toys or people by 12 months","No pretend play by 2 years","Repetitive, rigid play only (possible autism)","Excessive screen time replacing play"],
  viva:[["Name Parten's stages.","Unoccupied, solitary, onlooker, parallel, associative, cooperative."],["What is parallel play?","Children play beside each other with similar toys but not together."],["Name Piaget's play types.","Functional, symbolic, games with rules."]],
  refs:[{b:"hurlock",ch:"Play"},{b:"bundy",ch:"Play and playfulness"},{b:"caseSmith",ch:"Play"},{c:"Lillard AS, Lerner MD, Hopkins EJ, et al. The impact of pretend play on children's development: a review of the evidence. Psychol Bull. 2013;139(1):1-34.", q:"Lillard impact of pretend play children's development review"}],
  keywords:"play parten piaget types stages pretend play disability playfulness",
  mcq:[["Two children playing side by side with similar toys but not interacting are in:",["Solitary play","Parallel play","Cooperative play","Onlooker play"],1,"Typical at about 2-3 years."],["Symbolic play belongs to which Piagetian stage?",["Sensorimotor","Preoperational","Concrete operational","Formal operational"],1,"Pretend play peaks about 2-7 years."]]
}
]);
